{
  "version": 1,
  "state": [
    {
      "id": "pending",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"pending\""
        ]
      },
      "label": "Waiting for the compile"
    },
    {
      "id": "resolved",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"resolved\""
        ]
      },
      "label": "Resolved with the first model"
    },
    {
      "id": "failure",
      "when": {
        "eq": [
          {
            "var": "firstKind"
          },
          "\"failure\""
        ]
      },
      "label": "Rejected after worker failure"
    },
    {
      "id": "error",
      "when": {
        "eq": [
          {
            "var": "firstKind"
          },
          "\"error\""
        ]
      },
      "label": "Rejected after worker error"
    },
    {
      "id": "timeout",
      "when": {
        "eq": [
          {
            "var": "firstKind"
          },
          "\"timeout\""
        ]
      },
      "label": "Rejected after timeout"
    },
    {
      "id": "all",
      "when": true,
      "label": "Compile state"
    }
  ],
  "step": [
    {
      "id": "done",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"pending\""
            ]
          },
          {
            "eq": [
              {
                "to": "firstKind"
              },
              "\"done\""
            ]
          }
        ]
      },
      "label": "Done message wins"
    },
    {
      "id": "failure",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"pending\""
            ]
          },
          {
            "eq": [
              {
                "to": "firstKind"
              },
              "\"failure\""
            ]
          }
        ]
      },
      "label": "Failure message wins"
    },
    {
      "id": "error",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"pending\""
            ]
          },
          {
            "eq": [
              {
                "to": "firstKind"
              },
              "\"error\""
            ]
          }
        ]
      },
      "label": "Worker error wins"
    },
    {
      "id": "timeout",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "status"
              },
              "\"pending\""
            ]
          },
          {
            "eq": [
              {
                "to": "firstKind"
              },
              "\"timeout\""
            ]
          }
        ]
      },
      "label": "Timeout wins"
    },
    {
      "id": "all",
      "when": true,
      "label": "Keep the first outcome"
    }
  ]
}

